imitive":"min_shift","label":"Mindst 3 timer pr. fremmøde","source":"Eksempel § 8","todo_jura":"Fiktiv minimumsvagt.","params":{"min_minutes":180,"guarantee_pay":true,"pay_code":"GARANTI"}},{"id":"raadighed","primitive":"on_call","label":"Rådighed og tilkald","source":"Eksempel § 9","todo_jura":"Fiktive satser.","params":{"amount":{"type":"ore_per_hour","ore":2000},"pay_code":"RAADIGHED","call_out_min_minutes":180,"call_out_guarantee_pay_code":"TILKALD_GARANTI"}},{"id":"natarbejde","primitive":"night_work","label":"Natarbejde","source":"Eksempel § 10","todo_jura":"Fiktiv definition af nattetid.","params":{"from":"23:00","to":"06:00","night_shift_min_minutes":180,"max_average_daily_minutes":480,"reference_days":7}},{"id":"fravaer","primitive":"absence","label":"Fravær","source":"Eksempel § 11","todo_jura":"Fiktive fraværstyper og betaling.","params":{"types":[{"code":"sick","label":"Sygdom","payment":"full","pay_code":"SYG","counts_towards_norm":true},{"code":"child_sick","label":"Barns første sygedag","payment":"full","pay_code":"BARN_SYG","counts_towards_norm":true},{"code":"care_day","label":"Omsorgsdag","payment":"full","pay_code":"OMSORG","counts_towards_norm":true,"entitlement":{"days":2,"period":"calendar_year","accrual":"upfront"}},{"code":"unpaid_leave","label":"Tjenestefri uden løn","payment":"none","pay_code":null,"counts_towards_norm":false}]}},{"id":"ferie","source":"Eksempel § 12 (feriefridage)","todo_jura":"Fiktivt antal feriefridage.","params":{"extra_days":{"days_per_year":5,"year_start":"05-01","accrual":"upfront"}}},{"id":"varsling","primitive":"notice","label":"Varsling af vagtplan","source":"Eksempel § 13","todo_jura":"Fiktivt varsel.","params":{"publish_notice_days":14,"change_notice_hours":96}},{"id":"weekendfri","primitive":"weekend_off","label":"Fri weekender","source":"Eksempel § 14","todo_jura":"Fiktivt antal fri weekender.","params":{"weekends_off":2,"per_weeks":4}}]}$agreement_doc$::jsonb
