d_sick","label":"Barns 1. sygedag","payment":"full","pay_code":"BARN_SYG","counts_towards_norm":true,"paid_from_seniority_months":9},{"code":"child_sick_extra","label":"Barns 2. og 3. sygedag (uden løn)","payment":"none","pay_code":null,"counts_towards_norm":true},{"code":"child_hospital","label":"Barns hospitalsindlæggelse","payment":"full","pay_code":"BARN_HOSP","counts_towards_norm":true,"entitlement":{"days":5,"period":"calendar_year","accrual":"upfront"}},{"code":"child_care_day","label":"Børneomsorgsdag (uden løn)","payment":"none","pay_code":null,"counts_towards_norm":true,"entitlement":{"days":2,"period":"holiday_year","accrual":"upfront","min_seniority_months":9}},{"code":"grandchild_care_day","label":"Børnebørns-omsorgsdag (uden løn)","payment":"none","pay_code":null,"counts_towards_norm":true,"entitlement":{"days":2,"period":"holiday_year","accrual":"upfront","min_seniority_months":9}},{"code":"relative_escort","label":"Ledsagelse af nærtstående (uden løn)","payment":"none","pay_code":null,"counts_towards_norm":true,"entitlement":{"days":2,"period":"holiday_year","accrual":"upfront","min_seniority_months":9}},{"code":"child_doctor","label":"Lægebesøg med barn (uden løn)","payment":"none","pay_code":null,"counts_towards_norm":true},{"code":"senior_day","label":"Seniorfridag (uden løn)","payment":"none","pay_code":null,"counts_towards_norm":true},{"code":"funeral","label":"Begravelse","payment":"none","pay_code":null,"counts_towards_norm":true}]}},{"id":"ferie","label":"Ferie og feriefridage","source":"§ 18 stk. 2 og § 40","todo_jura":"Feriefridage tildelt fra 1/9-2025 afholdes uden løn og betales via Fritvalgs Lønkonto (§ 25 stk. 2), som lønsystemet håndterer. Ferie ud over 20 dage kan overføres efter skriftlig aftale (§ 40 stk. 6).","params":{"extra_days":{"days_per_year":5,"year_start":"09-01","accrual":"upfront","min_seniority_months":9},"transfer":{"allowed":true,"only_above_days":20}}}]},{"id":"industriens-overenskomst","name":"Industriens Overenskomst 2025–2028","kind":"agreement","version":3,"valid_from":"2027-03-01","valid_to":null,"inherits_from":"basis-dk","source":"Industriens Overenskomst 2025–2028 (CO-industri og DI), udgave 31/7-2025","example":false,"description":"Timelønnede under Industriens Overenskomst. Personalegrupper (feltet på kontrakten): Dagarbejde, Forskudt tid, Skiftehold og Weekend. Satserne er overenskomstens; den enkeltes løn aftales lokalt (§ 22 stk. 2) og sættes på kontrakten.","pay_codes":{"TIMELOEN":{"label":"Timeløn"},"OT_1_2":{"label":"Overarbejde 1.–2. klokketime"},"OT_3_4":{"label":"Overarbejde 3.–4. klokketime"},"OT_5":{"label":"Overarbejde 5. klokketime og derefter"},"OT_FOER_DAG":{"label":"Overarbejde før arbejdstid 06–18"},"OT_FOER_NAT":{"label":"Overarbejde før arbejdstid 18–06"},"OT_FRIDAG_DAG":{"label":"Overarbejde på hverdagsfridag 06–18"},"OT_FRIDAG_NAT":{"label":"Overarbejde på hverdagsfridag 18–06"},"OT_SOEN_FM":{"label":"Søn- og helligdag til kl. 12"},"OT_SOEN_EM":{"label":"Søn- og helligdag efter kl. 12 og om natten"},"AFSPADSERING":{"label":"Afspadsering (overarbejdstimer)"},"FORSKUDT_1":{"label":"Forskudt tid, tillæg 1 (18–22)"},"FORSKUDT_2":{"label":"Forskudt tid, tillæg 2 (22–06)"},"FORSKUDT_3":{"label":"Forskudt tid, tillæg 3 (påbegyndt kl. 24 eller senere)"},"SKIFT_1":{"label":"Skiftehold, tillæg 1 (hverdage 18–06)"},"SKIFT_2":{"label":"Skiftehold, tillæg 2 (weekend og helligdage)"},"WEEKEND_LOER":{"label":"Weekendarbejde lørdag 06–18"},"WEEKEND_NAT":{"label":"Weekendarbejde lørdag 18–06"},"WEEKEND_SOEN_FM":{"label":"Weekendarbejde søn- og helligdag til kl. 12"},"WEEKEND_SOEN_EM":{"label":"Weekendarbejde søn- og helligdag efter kl. 12"},"SYG":{"label":"Sygdom"},"SYG_TILSKADE":{"label":"Tilskadekomst"},"BARN_SYG":{"label":"Barns 1. sygedag"},"BARN_HOSP":{"label":"Barns hospitalsindlæggelse"}},"rules":[{"id":"helligdage","label":"Helligdage og overenskomstmæssige fridage","source":"§ 18 stk. 1 og § 13 stk. 7 nr. 1 b","todo_jura":"1. maj, grundlovsdag og juleaftensdag regnes efter overenskomsten fra kl. 06.00 (eller normal arbejdstids begyndelse) til næste dag. Turnus bruger kalenderdøgnet. Grundlovsdag er hverdagsfridag til kl. 12 og søn- og helligdag derefter.","params":{"holidays":["nytaarsdag","skaertorsdag","langfredag","paaskedag","anden_paaskedag","kristi_himmelfartsdag","pinsedag","anden_pinsedag","juledag","anden_juledag","foerste_maj","grundlovsdag","juleaftensdag"],"partial":[{"key":"grundlovsdag","from":"12:00"}]}},{"id":"timeloen","primitive":"pay_rate","label":"Mindstebetaling","source":"§ 22 stk. 1","todo_jura":"Overenskomstens mindstebetaling. Den enkeltes løn aftales lokalt (§ 22 stk. 2) og indtastes som en sats på kontrakten eller i en lokalaftale. Lærlinge og elever (del 3) har egne satser.","params":{"pay_code":"TIMELOEN","rates":[{"min_age":18,"hourly_ore":14690},{"max_age":18,"hourly_ore":8460}]}},{"id":"normtid","primitive":"norm","label":"37 timer, nedsat med 1/5 for helligdage på hverdage","source":"§ 9 stk. 1, § 11 stk. 2, § 15 stk. 4.1","todo_jura":"Ugenormen står på kontrakten: 37 timer (dag, forskudt, skiftehold 1. skift, weekend 37 timer svarende til 24), 34 timer på 2. og 3. skift, 35/35,5/34 timer i turnus. Varierende ugentlig arbejdstid over 12 måneder (§ 9 stk. 2) sættes op som normperiode i en lokalaftale.","params":{"period":{"type":"week"},"holiday_reduction":"one_fifth_on_weekdays"}},{"id":"overarbejde","primitive":"overtime","label":"Overarbejde efter klokketimer og tidsrum","source":"§ 13 stk. 2, 7 og 8","todo_jura":"Normal arbejdstids begyndelse er sat til kl. 06.00 (tidsrummene på søn- og helligdage). Ret til virksomhedens tid. Afspadseringsfrit overarbejde (stk. 8 nr. 4: aftale med tillidsrepræsentanten, under 12 timer på 4 uger ved fuld tid, sygeafløsning m.m.) vurderes ikke automatisk: sæt betalingen til 'Tillæg udbetales' i en lokalaftale. Deltidsansattes overarbejde (stk. 7 nr. 1 d) beregnes som for fuldtid.","params":{"trigger":"outside_planned","tier_basis":"since_planned_end","compensation":"payout_and_time_off","time_off_pay_code":"AFSPADSERING","tiers":[{"up_to_minutes":120,"amount":{"type":"ore_per_hour","ore":4955},"pay_code":"OT_1_2"},{"up_to_minutes":120,"amount":{"type":"ore_per_hour","ore":7910},"pay_code":"OT_3_4"},{"up_to_minutes":null,"amount":{"type":"ore_per_hour","ore":14800},"pay_code":"OT_5"}],"window_rates":[{"days":["sun","holiday"],"from":"06:00","to":"12:00","amount":{"type":"ore_per_hour","ore":9860},"pay_code":"OT_SOEN_FM"},{"days":["sun","holiday"],"from":"12:00","to":"06:00","amount":{"type":"ore_per_hour","ore":14800},"pay_code":"OT_SOEN_EM"},{"days":["sun","holiday"],"from":"00:00","to":"06:00","amount":{"type":"ore_per_hour","ore":14800},"pay_code":"OT_SOEN_EM"},{"days":["any"],"from":"06:00","to":"18:00","when":"before_planned","amount":{"type":"ore_per_hour","ore":4955},"pay_code":"OT_FOER_DAG"},{"days":["any"],"from":"18:00","to":"06:00","when":"before_planned","amount":{"type":"ore_per_hour","ore":14800},"pay_code":"OT_FOER_NAT"},{"days":["any"],"from":"06:00","to":"18:00","when":"day_off","amount":{"type":"ore_per_hour","ore":7910},"pay_code":"OT_FRIDAG_DAG"},{"days":["any"],"from":"18:00","to":"06:00","when":"day_off","amount":{"type":"ore_per_hour","ore":14800},"pay_code":"OT_FRIDAG_NAT"}]}},{"id":"forskudt-1","primitive":"time_window_supplement","label":"Forskudt tid, tillæg 1","source":"§ 14 stk. 6","applies_to":{"staff_groups":["Forskudt tid"]},"params":{"windows":[{"days":["mon","tue","wed","thu","fri"],"from":"18:00","to":"22:00"}],"amount":{"type":"ore_per_hour","ore":3375},"pay_code":"FORSKUDT_1"}},{"id":"forskudt-2","primitive":"time_window_supplement","label":"Forskudt tid, tillæg 2","source":"§ 14 stk. 6","todo_jura":"\"Hverdage\" er sat til mandag–fredag (aftenen), så natten til lørdag er med, men natten til mandag ikke.","applies_to":{"staff_groups":["Forskudt tid"]},"stacking":{"mode":"highest","group":"forskudt-nat"},"params":{"windows":[{"days":["mon","tue","wed","thu","fri"],"from":"22:0