ore":7910},"pay_code":"WEEKEND_LOER"}},{"id":"weekend-nat","primitive":"time_window_supplement","label":"Weekendarbejde lørdag 18 – søndag 06","source":"§ 10 stk. 5 og § 13 stk. 7 nr. 2 b","applies_to":{"staff_groups":["Weekend"]},"stacking":{"mode":"highest","group":"weekend"},"params":{"windows":[{"days":["sat"],"from":"18:00","to":"06:00"}],"amount":{"type":"ore_per_hour","ore":14800},"pay_code":"WEEKEND_NAT"}},{"id":"weekend-soendag-fm","primitive":"time_window_supplement","label":"Weekendarbejde søn- og helligdag 06–12","source":"§ 10 stk. 5 og § 13 stk. 7 nr. 2 c","applies_to":{"staff_groups":["Weekend"]},"stacking":{"mode":"highest","group":"weekend"},"params":{"windows":[{"days":["sun","holiday"],"from":"06:00","to":"12:00"}],"amount":{"type":"ore_per_hour","ore":9860},"pay_code":"WEEKEND_SOEN_FM"}},{"id":"weekend-soendag-em","primitive":"time_window_supplement","label":"Weekendarbejde søn- og helligdag efter 12 og før 06","source":"§ 10 stk. 5 og § 13 stk. 7 nr. 2 c","applies_to":{"staff_groups":["Weekend"]},"stacking":{"mode":"highest","group":"weekend"},"params":{"windows":[{"days":["sun","holiday"],"from":"12:00","to":"06:00"},{"days":["sun","holiday"],"from":"00:00","to":"06:00"}],"amount":{"type":"ore_per_hour","ore":14800},"pay_code":"WEEKEND_SOEN_EM"}},{"id":"dagarbejde-tidsrum","primitive":"remark","label":"Dagarbejde ligger mellem kl. 06 og 18","source":"§ 9 stk. 1","severity":"WARNING","applies_to":{"staff_groups":["Dagarbejde"]},"params":{"code":"DAGARBEJDE_FOER_06","message":"Normal arbejdstid ved dagarbejde ligger mellem kl. 06 og 18. Ellers er det forskudt tid eller overarbejde.","show_in":["schedule"],"condition":{"type":"starts_before","time":"06:00"}}},{"id":"dagarbejde-slut","primitive":"remark","label":"Dagarbejde slutter senest kl. 18","source":"§ 9 stk. 1","severity":"WARNING","applies_to":{"staff_groups":["Dagarbejde"]},"params":{"code":"DAGARBEJDE_EFTER_18","message":"Normal arbejdstid ved dagarbejde ligger mellem kl. 06 og 18. Ellers er det forskudt tid eller overarbejde.","show_in":["schedule"],"condition":{"type":"ends_after","time":"18:00"}}},{"id":"dagarbejde-6-timer","primitive":"remark","label":"Mindst 6 timer pr. arbejdsdag ved 5-dages uge","source":"§ 9 stk. 1","severity":"INFO","applies_to":{"staff_groups":["Dagarbejde"]},"params":{"code":"ARBEJDSDAG_UNDER_6","message":"Når ugen er fordelt på 5 dage, må ingen arbejdsdag være under 6 timer, medmindre andet er aftalt lokalt.","show_in":["schedule"],"condition":{"type":"shift_shorter_than","minutes":360}}},{"id":"varsel-forskudt-skift","primitive":"notice","label":"5 × 24 timers varsel ved forskudt tid og skiftehold","source":"§ 14 stk. 5 og 7, § 15 stk. 5.3 og 8.1","todo_jura":"Varslet gælder etablering af og ændring til anden forskudt tid/skiftehold. Akut overflytning (§ 15 stk. 7 d) kræver ikke varsel, men giver tillæg 5 (tillægstype i Opsætning).","applies_to":{"staff_groups":["Forskudt tid","Skiftehold"]},"params":{"change_notice_hours":120}},{"id":"fravaer","primitive":"absence","label":"Fravær","source":"§ 29, § 30, § 32 og § 33","todo_jura":"Sygeløn efter 5 uger (yderligere højst 12 uger fuld løn uden genetillæg) og ophør ved manglende refusion beregnes ikke. Hospitalsindlæggelse er 5 dage pr. 12 måneder (her pr. kalenderår). Børneomsorgsdage m.fl. er pr. ferieafholdelsesperiode (her pr. ferieår). Ledsagelse ved kritisk sygdom (yderligere 5 dage) og begravelse registreres uden saldo.","params":{"types":[{"code":"sick","label":"Sygdom","payment":"full","pay_code":"SYG","counts_towards_norm":true,"paid_from_seniority_months":6},{"code":"work_injury","label":"Tilskadekomst","payment":"full","pay_code":"SYG_TILSKADE","counts_towards_norm":true},{"code":"child_sick","label":"Barns 1. sygedag","payment":"full","pay_code":"BARN_SYG","counts_towards_norm":true,"paid_from_seniority_months":9},{"code":"child_sick_extra","label":"Barns 2. og 3. sygedag (uden løn)","payment":"none","pay_code":null,"counts_towards_norm":true},{"code":"child_ho